window.EW=window.EW||{pages:{}};window.EW.pages["livre-potions-enseignees"]={"html":"<div class=\"doc-toc\"><p>Académie d’Elderwood<\/p><p>Livre des potions<\/p><p>Année 1<\/p><p>Potion de Soins Commune<\/p><\/div><p>Tier : T1<\/p><p>Année : 1ere année<\/p><p>Effet : restaure 10 % des HP.<\/p><p>Cooldown : 30 secondes.<\/p><p>Matériel nécessaire : chaudron, baguette, fiole.<\/p><h4 id=\"ingredients\">Ingrédients :<\/h4><ul><li>1 Queue de Folumix<\/li><li>3 Feuille de Dictame de Crête<\/li><li>5 Fruit d'Obligeante des haies<\/li><li>1 Eau de lune<\/li><\/ul><h4 id=\"preparation\">Préparation :<\/h4><ol class=\"lit\"><li><span class=\"n\">1.<\/span> Ajouter 1 Eau de lune : température entre 60 et 90 °C.<\/li><li><span class=\"n\">2.<\/span> Ajouter 3 feuilles de Dictame de Crête.<\/li><li><span class=\"n\">3.<\/span> Maintenir entre 70 et 100 °C pendant 4 s.<\/li><li><span class=\"n\">4.<\/span> Mélanger à droite 4 fois.<\/li><li><span class=\"n\">5.<\/span> Ajouter 5 Fruit d'Obligeante des haies.<\/li><li><span class=\"n\">6.<\/span> Monter entre 110 et 140 °C pendant 3 s.<\/li><li><span class=\"n\">7.<\/span> Mélanger à gauche 3 fois.<\/li><li><span class=\"n\">8.<\/span> Ajouter 1 Queue de Folumix.<\/li><li><span class=\"n\">9.<\/span> Tapoter 2 fois.<\/li><li><span class=\"n\">10.<\/span> Maintenir entre 120 et 150 °C pendant 4 s.<\/li><li><span class=\"n\">11.<\/span> Mélanger à droite 5 fois.<\/li><li><span class=\"n\">12.<\/span> Éteindre / mettre en fiole.<\/li><\/ol><p>Année 2<\/p><p>Potion de Flux Commune<\/p><p>Tier : T1<\/p><p>Année : 2e année<\/p><p>Effet : restaure 10 % du Flux.<\/p><p>Cooldown : 30 secondes.<\/p><p>Nécessaire : chaudron, baguette, fiole.<\/p><h4 id=\"ingredients-2\">Ingrédients :<\/h4><ul><li>1 Tige confite d'Angélique d'Elderwood<\/li><li>4 Jus de baie de Lyandrelle<\/li><li>2 Plume de Brumeret<\/li><li>1 Griffe d'Arcanophage<\/li><li>1 Eau<\/li><\/ul><h4 id=\"preparation-2\">Préparation :<\/h4><ol class=\"lit\"><li><span class=\"n\">1.<\/span> Ajouter 1 Eau : température entre 50 et 80 °C.<\/li><li><span class=\"n\">2.<\/span> Ajouter 4 Jus de baie de Lyandrelle.<\/li><li><span class=\"n\">3.<\/span> Mélanger à gauche 4 fois.<\/li><li><span class=\"n\">4.<\/span> Ajouter 1 Tige confite d'Angélique d'Elderwood.<\/li><li><span class=\"n\">5.<\/span> Maintenir entre 90 et 120 °C pendant 4 s.<\/li><li><span class=\"n\">6.<\/span> Ajouter 2 Plume de Brumeret.<\/li><li><span class=\"n\">7.<\/span> Mélanger à droite 5 fois.<\/li><li><span class=\"n\">8.<\/span> Monter entre 130 et 160 °C.<\/li><li><span class=\"n\">9.<\/span> Ajouter 1 Griffe d'Arcanophage.<\/li><li><span class=\"n\">10.<\/span> Souffler 2 fois.<\/li><li><span class=\"n\">11.<\/span> Maintenir entre 130 et 160 °C pendant 3 s.<\/li><li><span class=\"n\">12.<\/span> Éteindre / mettre en fiole.<\/li><\/ol><hr><p>Potion de Force de Flux Remarquable<\/p><p>Tier : T1<\/p><p>Année : 2e année<\/p><p>Effet : augmente temporairement la puissance du Flux, plutôt que de restaurer sa réserve.<\/p><p>Cooldown : …<\/p><p>Nécessaire : chaudron, baguette, fiole.<\/p><h4 id=\"ingredients-3\">Ingrédients :<\/h4><ul><li>3 Feuille de Dictame de Crête<\/li><li>2 Osmium raffiné<\/li><li>2 Chapeau de Mycollin<\/li><li>1 Plume de Brumeret<\/li><li>1 Eau de lune<\/li><\/ul><h4 id=\"preparation-3\">Préparation :<\/h4><ol class=\"lit\"><li><span class=\"n\">1.<\/span> Ajouter 1 Eau de lune : température entre 70 et 100 °C.<\/li><li><span class=\"n\">2.<\/span> Ajouter 2 Chapeau de Mycollin.<\/li><li><span class=\"n\">3.<\/span> Mélanger à gauche 5 fois.<\/li><li><span class=\"n\">4.<\/span> Maintenir entre 100 et 130 °C pendant 4 s.<\/li><li><span class=\"n\">5.<\/span> Ajouter 3 feuilles de Dictame de Crête.<\/li><li><span class=\"n\">6.<\/span> Mélanger à droite 7 fois.<\/li><li><span class=\"n\">7.<\/span> Monter entre 160 et 190 °C.<\/li><li><span class=\"n\">8.<\/span> Ajouter 2 Osmium raffinés.<\/li><li><span class=\"n\">9.<\/span> Maintenir pendant 5 s.<\/li><li><span class=\"n\">10.<\/span> Tapoter 3 fois.<\/li><li><span class=\"n\">11.<\/span> Diminuer la température entre 120 et 150 °C.<\/li><li><span class=\"n\">12.<\/span> Ajouter 1 Plume de Brumeret.<\/li><li><span class=\"n\">13.<\/span> Mélanger à gauche 8 fois.<\/li><li><span class=\"n\">14.<\/span> Souffler 2 fois.<\/li><li><span class=\"n\">15.<\/span> Mélanger à droite 4 fois.<\/li><li><span class=\"n\">16.<\/span> Éteindre / mettre en fiole.<\/li><\/ol><hr><p>Antidote universel<\/p><p>Tier : T1<\/p><p>Année : 2e année<\/p><p>Effet : neutralise de nombreux poisons courants, mais reste inefficace contre certains poisons rares, complexes ou spécifiquement magiques.<\/p><p>Cooldown : …<\/p><p>Nécessaire : chaudron, baguette, fiole.<\/p><h4 id=\"ingredients-4\">Ingrédients :<\/h4><ul><li>3 Champignon bruns<\/li><li>1 Jus de baie de Lyandrelle<\/li><li>1 Eau<\/li><\/ul><h4 id=\"preparation-4\">Préparation :<\/h4><ol class=\"lit\"><li><span class=\"n\">1.<\/span> Ajouter 1 Eau : température entre 60 et 90°C.<\/li><li><span class=\"n\">2.<\/span> Ajouter 1 Jus de baie de Lyandrelle.<\/li><li><span class=\"n\">3.<\/span> Mélanger à droite 3 fois.<\/li><li><span class=\"n\">4.<\/span> Maintenir entre 90 et 120°C pendant 4 s.<\/li><li><span class=\"n\">5.<\/span> Ajouter 3 champignons bruns.<\/li><li><span class=\"n\">6.<\/span> Mélanger à gauche 6 fois.<\/li><li><span class=\"n\">7.<\/span> Tapoter 3 fois.<\/li><li><span class=\"n\">8.<\/span> Monter la température entre 140 et 170°C pendant 3 s.<\/li><li><span class=\"n\">9.<\/span> Mélanger à droite 3 fois.<\/li><li><span class=\"n\">10.<\/span> Éteindre / mettre en fiole.<\/li><\/ol><hr><p>Année 3<\/p><p>Potion de Bouclier Commune<\/p><p>Tier : T1<\/p><p>Année : 3eme année<\/p><p>Effet : confère temporairement au consommateur une protection contre les dégâts magiques. Cooldown : … (La valeur exacte de la réduction et la durée restent à définir selon l’équilibrage du gameplay).<\/p><p>Nécessaire : chaudron, baguette, fiole.<\/p><h4 id=\"ingredients-5\">Ingrédients :<\/h4><ul><li>1 Osmium raffiné<\/li><li>1 Chapeau de Mycollin<\/li><li>1 Eau de lune<\/li><\/ul><h4 id=\"preparation-5\">Préparation :<\/h4><ol class=\"lit\"><li><span class=\"n\">1.<\/span> Ajouter 1 Eau de lune : température entre 50 et 80 °C.<\/li><li><span class=\"n\">2.<\/span> Ajouter 1 Chapeau de Mycollin.<\/li><li><span class=\"n\">3.<\/span> Maintenir entre 70 et 100 °C pendant 4 s.<\/li><li><span class=\"n\">4.<\/span> Mélanger à droite 4 fois.<\/li><li><span class=\"n\">5.<\/span> Monter la température entre 120 et 150 °C.<\/li><li><span class=\"n\">6.<\/span> Ajouter 1 Osmium raffiné.<\/li><li><span class=\"n\">7.<\/span> Maintenir entre 130 et 160 °C pendant 4 s.<\/li><li><span class=\"n\">8.<\/span> Tapoter 2 fois.<\/li><li><span class=\"n\">9.<\/span> Mélanger à gauche 5 fois.<\/li><li><span class=\"n\">10.<\/span> Souffler 2 fois.<\/li><li><span class=\"n\">11.<\/span> Diminuer la température entre 80 et 110 °C pendant 3 s.<\/li><li><span class=\"n\">12.<\/span> Mélanger à droite 3 fois.<\/li><li><span class=\"n\">13.<\/span> Éteindre / mettre en fiole.<\/li><\/ol><hr><p>Potion d'Exploration Intérieure (ENYMA)<\/p><p>Tier : T1<\/p><p>Année : 3e année<\/p><p>Effet : provoque un état d’introspection magique profonde facilitant l’accès aux souvenirs, émotions et représentations mentales. Enne ne révèle pas automatiquement la vérité et ne restaure pas un souvenir détruit.<\/p><p>Cooldown : …<\/p><p>Nécessaire : chaudron, baguette, fiole.<\/p><h4 id=\"ingredients-6\">Ingrédients :<\/h4><ul><li>1 Racine de Prenante des rives<\/li><li>1 Corne de Jackalope<\/li><li>1 Queue de Bondiluce<\/li><li>3 Sang de Pastenague<\/li><li>1 Eau<\/li><\/ul><h4 id=\"preparation-6\">Préparation :<\/h4><ol class=\"lit\"><li><span class=\"n\">1.<\/span> Ajouter 1 Eau et 1 racine de Prenante des rives : température entre 20 et 45°C.<\/li><li><span class=\"n\">2.<\/span> Maintenir le feu entre 25 et 45°C pendant 4 s.<\/li><li><span class=\"n\">3.<\/span> Mélanger à gauche 7 fois.<\/li><li><span class=\"n\">4.<\/span> Ajouter 1 Corne de Jackalope : feu entre 25 et 55°C.<\/li><li><span class=\"n\">5.<\/span> Tapoter 3 fois.<\/li><li><span class=\"n\">6.<\/span> Maintenir le feu entre 55 et 75°C pendant 4 s.<\/li><li><span class=\"n\">7.<\/span> Ajouter 1 queue de Bondiluce : feu entre 50 et 80°C.<\/li><li><span class=\"n\">8.<\/span> Mélanger à droite 6 fois.<\/li><li><span class=\"n\">9.<\/span> Souffler 4 fois.<\/li><li><span class=\"n\">10.<\/span> Ajouter 3 sang de Pastenague : feu entre 40 et 70°C.<\/li><li><span class=\"n\">11.<\/span> Maintenir le feu entre 70 et 90°C pendant 4 s.<\/li><li><span class=\"n\">12.<\/span> Mélanger à gauche 9 fois.<\/li><li><span class=\"n\">13.<\/span> Souffler 3 fois.<\/li><li><span class=\"n\">14.<\/span> Éteindre / mettre en fiole.<\/li><\/ol>","toc":[]};
